$failed = @(); $none = @()
foreach ($f in Get-ChildItem logs -File -Filter *.log) {
  $last = [IO.File]::ReadAllLines($f.FullName) | ? { $_.StartsWith('STATUS:') } | Select -Last 1
  if (-not $last) { $none += $f.BaseName; continue }
  if ($last.Substring(7).Trim() -eq 'FAILED') { $failed += $f.BaseName }
}
$failed = [string[]]($failed | Sort-Object { $_ } -Culture 'en-US' -CaseSensitive)
[Array]::Sort($failed, [StringComparer]::Ordinal)
"no status: $($none -join ',')"
$json = [ordered]@{ failed_count = $failed.Count; failed_jobs = $failed } | ConvertTo-Json -Compress
[IO.File]::WriteAllText("$PWD\report.json", $json)
$json

